/* Factory Board v3 — reads the SM tick's state snapshots, no build step.
 *
 * v2 (owner 2026-10-01):
 *  - schema 1 AND schema 2 snapshots render (old history never breaks);
 *  - lifecycle timestamps: card age in its current lane + a mini SVG
 *    timeline of the pipeline transitions (tooltips carry the times);
 *  - tab switches clear the board to a skeleton instantly, fetches are
 *    single-flight (AbortController) and only the LAST request renders —
 *    a failed fetch can no longer leave the previous factory's lanes up.
 *
 * v3 (owner 2026-10-03):
 *  - readable progress: per-lane summary line (N total · done · in-flight ·
 *    queued · blocked) + a thin segmented progress bar per lane — the cards
 *    and dots stay as decoration;
 *  - details drawer: click any PR/issue card for an inline panel with the
 *    header (number, title, head sha, state + labels, GitHub link), the
 *    full state history (snapshot-accumulated card.history, newest first),
 *    per-state timings with proportional bars, and the OPTIONAL per-leg
 *    token table (graceful "—" when the factory doesn't report tokens);
 *  - issue backlog lanes: the snapshot's `backlog` section renders as four
 *    columns (in dev / agent:dev queued / blocked / inbox) — blocked is
 *    its own, visually distinct, owner-hold column;
 *  - ?fixture=<url> renders a bundled sample snapshot (deterministic
 *    visual-check screenshots, no network); ?drawer=pr-817 deep-links the
 *    drawer.
 *
 * gh-726 (owner 2026-10-04):
 *  - the lanes never wrap: fixed compact lane width + horizontal scroll —
 *    any lane count renders as ONE left→right strip (the 7th lane used to
 *    drop to a lone wrapped row);
 *  - dots → labeled stepper: the per-card status strip shows six NAMED
 *    steps (dev → pr → valid → review → approve → merge), each colored by
 *    state (done / current / pending / failed); the exact pipeline position
 *    reads off the strip alone. Logic lives in steps.js (unit-tested).
 *
 * v4 value stream (gh-769, owner 2026-10-06):
 *  - labeled rollups: the counts pill names each lane (dev · pr · ci · …)
 *    and a snapshot older than config.staleAfterMs announces itself as
 *    STALE — a stalled tick can no longer masquerade as repo reality;
 *  - merge-readiness: every card carries a "▸ next" line (merge / rework /
 *    approve …) with the concrete blocker (queue #1 of 3 — next on the
 *    mutex, CI red, owner hold); the approved-queue head is the board's
 *    "next up" chip. Logic lives in flow.js nextStep (unit-tested);
 *  - CI vs idle: validating chips split CI wall-time from queue wait via
 *    checks.runStartedAt/updatedAt (flow.js ciSplit);
 *  - phase rail: the drawer's history collapses rework cycles into named
 *    phases with round counts (PR created ×3) and first-pass vs rework
 *    time (flow.js phaseRail);
 *  - rework + token analytics: per-card rework ×N · time, Σ token chip on
 *    cards, and a board-level value-stream strip (flow.js flowSummary).
 *
 * gh-825 (model + $cost): the tick prices each token row against the
 * hardcoded data/model-pricing.json table (rates USD/Mtok; unknown/absent
 * model ⇒ cost omitted, tokens still shown). The board only sums: per-leg
 * rows render model + $ (drawer token table), cards gain Σ$ on the token
 * chip and the drawer total row, the flow-strip chip gains the board Σ$,
 * and the header gains the tick-published global Σ$ pill (st.costs — all
 * cards, 14d window; hidden when the snapshot carries no costs).
 */
(function () {
  'use strict';
  var CFG = window.FACTORY_BOARD_CONFIG;
  // pure analytics (flow.js) — degraded no-ops if the script is missing,
  // the board keeps rendering everything it rendered before v4
  var FLOW = window.FACTORY_FLOW || {
    tokenTotals: function () { return null; },
    ciSplit: function () { return null; },
    phaseRail: function () { return []; },
    reworkOf: function () { return { rounds: 0, ms: 0 }; },
    nextStep: function () { return null; },
    entriesOf: function () { return []; },
    flowSummary: function () { return null; }
  };
  var tabsEl = document.getElementById('factory-tabs');
  var lanesEl = document.getElementById('lanes');
  var backlogEl = document.getElementById('backlog');
  // cache-drift guard (review thread 3): skeleton()/render()/fail() all
  // write flowEl — a browser serving a stale index.html without the v4
  // <section id="flow"> next to this app.js must degrade to a no-op stub,
  // exactly like the missing flow.js script degrades to FLOW no-ops,
  // instead of throwing on first paint and killing the whole board.
  var flowEl = document.getElementById('flow') ||
    { innerHTML: '', hidden: true };
  var errEl = document.getElementById('error');
  var statusEl = document.getElementById('statusline');
  var drawerEl = document.getElementById('drawer');
  var backdropEl = document.getElementById('drawer-backdrop');
  var active = 0;
  var fetchSeq = 0;          // single-flight: only the newest request renders
  var inFlight = null;       // AbortController of the running fetch

  // ?fixture= (visual-check mode): fetch this URL instead of the live
  // stateUrl and pin "now" to the snapshot's tick — ages, durations and
  // bars render identically no matter when the screenshot is taken.
  var FIXTURE = null;
  try { FIXTURE = new URLSearchParams(location.search).get('fixture'); } catch (eF) {}
  // same-origin only: ?fixture= must never turn this board into a renderer
  // for arbitrary remote JSON (attacker-controlled cards under our origin).
  // Relative paths (visual-check) and same-origin absolute URLs pass; any
  // other scheme/host is dropped and the live snapshot loads instead.
  try {
    if (FIXTURE && (/^[a-z][a-z0-9+.-]*:/i.test(FIXTURE) ||
                    FIXTURE.lastIndexOf('//', 0) === 0) &&
        FIXTURE.indexOf(location.origin + '/') !== 0) {
      FIXTURE = null;
    }
  } catch (eFx) { FIXTURE = null; }
  var NOW_OVERRIDE = null;   // ms; set in fixture mode after the load
  // ?drawer=pr-817 → open that card's drawer once the board renders
  var DEEP_LINK = null;
  try { DEEP_LINK = new URLSearchParams(location.search).get('drawer'); } catch (eD) {}

  // render-time index: key 'pr-817'/'issue-315' → drawer context
  var boardIndex = {};

  // schema 1 lane id → schema 2 rendering lane, as RENDER-lookup: the v2
  // lane id whose data lives under the v1 key (fresh → pr_created)
  var LANE_ALIASES = { pr_created: 'fresh' };

  // lane id → the short name the counts pill uses (gh-769: an unlabeled
  // "0 · 1 · 0 · 9" rollup is unreadable — the owner can't tell which
  // number is which lane, so the header contradicts the repo at a glance)
  var LANE_SHORT = {
    development: 'dev', pr_created: 'pr', pr_validation: 'ci',
    review: 'review', approved_queue: 'queue', validating: 'mutex',
    merged_recent: 'merged'
  };

  // drawer value-stream row: the ciSplit label names the run's ROLE in the
  // card's CURRENT state — a validating card is on the mutex, a review
  // card's head run is the 'last run', not 'validating' (review thread 6;
  // ciSplit works on any card carrying a run verdict). Lanes outside the
  // PR pipeline (backlog columns) fall back to the neutral 'checks'.
  var RUNNING_LABELS = {
    pr_validation: 'validating',
    validating: 'mutex',
    review: 'last run'
  };

  // ── labeled stepper (gh-726): named stages, colored by state ──────────────
  // Logic (state computation, lane→step mapping, failed-verdict detection)
  // lives in steps.js — pure and unit-tested; this file only renders.
  function stepperHtml(c, laneId) {
    var steps = (window.FACTORY_STEPS || { stepStates: function () { return []; } })
      .stepStates(c, laneId);
    if (!steps.length) return '';
    var nodes = steps.map(function (s) {
      var tip = s.at
        ? s.name + ' · ' + clockTime(s.at) + ' (' + ago(s.at) + ')'
        : s.name + ' · not reached';
      return '<span class="step st-' + s.state + '" title="' + esc(tip) + '">' +
        '<span class="step-dot"></span>' +
        '<span class="step-name">' + esc(s.name) + '</span></span>';
    }).join('');
    var cur = steps.…

/*
 * Factory Board — value-stream flow analytics (gh-769, owner 2026-10-06).
 *
 * The board showed WHERE a card sat but not the shape of its flow: the
 * drawer repeated 'PR created' once per rework cycle, rework was
 * invisible, validating time mixed real CI wall-time with queue wait,
 * tokens hid in the drawer, and nothing said what happens NEXT for a
 * card. This module is the pure analytics layer behind the Lean
 * value-stream surfaces:
 *
 *   phaseRail    history [{state, at}] → named phases with boundaries
 *                (rounds collapse: 3× 'PR created' renders as ONE phase,
 *                ×3, with the time split into first pass vs rework);
 *   reworkOf     rail → {rounds, ms} per card;
 *   ciSplit      checks {at, runStartedAt?, updatedAt?} → {queueMs, ciMs}
 *                — CI wall-time vs queue wait (runner backlog / mutex);
 *   tokenTotals  card.tokens → Σ per leg (board-level token visibility);
 *   nextStep     card + lane → what happens next / what's blocking;
 *   flowSummary  all cards → the board-level value-stream strip.
 *
 * Everything degrades to honest unknowns (null / 0) on missing data —
 * schema-1 snapshots and pre-v3 cards render fine. Pure logic, zero DOM:
 * app.js renders the returned numbers; unit tests load the same file via
 * loadModule. Dual-exported — window.FACTORY_FLOW in the browser,
 * module.exports under the test harness.
 */
(function (root, factory) {
  var api = factory();
  if (typeof module !== 'undefined' && module.exports) { module.exports = api; }
  if (root) { root.FACTORY_FLOW = api; }
})(typeof window !== 'undefined' ? window : globalThis, function () {
  'use strict';

  // checks verdicts that mean the run is still in flight (mirrors
  // js/factoryState.js ACTIVE_RUN_STATES / steps.js usage)
  var ACTIVE_VERDICTS = ['queued', 'in_progress', 'waiting', 'pending'];

  // schema-2 card timestamp field → phase state — the drawer's history
  // fallback for cards accumulated before card.history existed (mirrors
  // js/factoryState.js LANE_ENTERED_AT / app.js LANE_ENTERED_AT, kept in
  // sync deliberately)
  var TS_TO_STATE = [
    { k: 'devStartedAt', state: 'development' },
    { k: 'prCreated',    state: 'pr_created' },
    { k: 'reviewedAt',   state: 'review' },
    { k: 'approvedAt',   state: 'approved_queue' },
    { k: 'validatingAt', state: 'validating' },
    { k: 'mergedAt',     state: 'merged_recent' }
  ];

  function parseMs(iso) {
    var t = Date.parse(iso);
    return isNaN(t) ? null : t;
  }

  // ── token totals (gh-769 #3: token spend visible beyond the drawer) ────────
  // {prompt, completion, total, cost, legs: {leg: {prompt, completion,
  // total, cost}}} or null when the card carries no token rows — tokens
  // stay OPTIONAL, factories that don't report them render without the chip.
  // cost (gh-825): the Σ$ the TICK priced per row (hardcoded table × the
  // row's model); the board only sums — a row without a cost (unknown or
  // absent model) keeps counting tokens and never invents a price, so the
  // Σ$ stays null until at least one priced row exists.
  function tokenTotals(card) {
    var rows = card && card.tokens;
    if (!rows || !rows.length) return null;
    // legs is prototype-less: leg names come from report input, so a
    // '__proto__'/'constructor' key must stay a plain bucket — a plain {}
    // would set the prototype (leg vanishes from Object.keys) or resolve
    // to the inherited Object function (NaN totals) (review thread 2)
    var out = { prompt: 0, completion: 0, total: 0, cost: null,
                legs: Object.create(null) };
    rows.forEach(function (r) {
      if (!r) return;
      var p = +r.prompt || 0, c = +r.completion || 0, t = +r.total || (p + c);
      var cost = (r.cost == null || r.cost === '' || isNaN(+r.cost)) ? null : +r.cost;
      out.prompt += p; out.completion += c; out.total += t;
      if (cost != null) out.cost = (out.cost || 0) + cost;
      var leg = r.leg || '—';
      var b = out.legs[leg];
      if (!b) { b = out.legs[leg] = { prompt: 0, completion: 0, total: 0, cost: null }; }
      b.prompt += p; b.completion += c; b.total += t;
      if (cost != null) b.cost = (b.cost || 0) + cost;
    });
    return out;
  }

  // ── CI wall-time vs queue wait (gh-769 #6) ──────────────────────────────────
  // checks.at  = run created_at (the clock started ticking — queue or CI)
  // runStartedAt = run_started_at (a runner actually picked it up)
  // updatedAt  = updated_at (terminal runs: the CI clock STOPPED here)
  // Returns {queueMs, ciMs, running}; unknown parts stay null. A completed
  // run without runStartedAt can't be split honestly → null.
  function ciSplit(card, nowMs) {
    var c = card && card.checks;
    if (!c || !c.at) return null;
    var created = parseMs(c.at);
    if (created == null) return null;
    var running = ACTIVE_VERDICTS.indexOf(c.verdict) >= 0;
    var start = c.runStartedAt ? parseMs(c.runStartedAt) : null;
    if (start == null) {
      if (!running) return null;                    // can't split — no fake
      // queued so far: everything since creation is wait
      return { queueMs: Math.max(0, nowMs - created), ciMs: null, running: true };
    }
    var queueMs = Math.max(0, start - created);
    if (running) {
      return { queueMs: queueMs, ciMs: Math.max(0, nowMs - start), running: true };
    }
    var end = c.updatedAt ? parseMs(c.updatedAt) : null;
